from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(status="captured", amt="80.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0)

# partial then full
x=p(); outage_refund(x,Decimal("30.00"),T0); assert x.status=="captured"
outage_refund(x,Decimal("50.00"),T0); assert x.status=="refunded" and x.refunded_amount==Decimal("80.00")
print("partial/full ok", audit.events("payment_refunded"))

# over refund
try: outage_refund(p(),Decimal("81.00"),T0)
except BillingError as e: print("over:",e.code)
# non-positive
for a in ("0","-1"):
    try: outage_refund(p(),Decimal(a),T0)
    except BillingError as e: print("nonpos:",e.code)
# not captured
try: outage_refund(p("authorized"),Decimal("1.00"),T0)
except BillingError as e: print("state:",e.code)
# approval threshold
try: outage_refund(p("captured","2000.00"),Decimal("1000.01"),T0)
except BillingError as e: print("approval:",e.code)
outage_refund(p("captured","2000.00"),Decimal("1000.00"),T0); print("at threshold ok")
outage_refund(p("captured","2000.00"),Decimal("1000.01"),T0,approved_by="mgr"); print("approved ok")
# return value
assert outage_refund(p(),Decimal("1.00"),T0).id=="pay_1"
print("all edge cases ok")
EOF"}

